function closestFarPair(nums: number[], x: number): number {
  if (x === 0) return 0;
  const vals = [...new Set(nums)].sort((a, b) => a - b);
  const m = vals.length;
  const rank = new Map<number, number>();
  vals.forEach((v, i) => rank.set(v, i + 1));
  const tree = new Int32Array(m + 1);
  const add = (i: number) => { for (; i <= m; i += i & -i) tree[i]++; };
  const prefix = (i: number) => { let s = 0; for (; i > 0; i -= i & -i) s += tree[i]; return s; };
  let top = 1;
  while (top * 2 <= m) top *= 2;
  // rank of the k-th smallest inserted value
  const kth = (k: number) => {
    let pos = 0;
    for (let step = top; step > 0; step >>= 1) {
      if (pos + step <= m && tree[pos + step] < k) { pos += step; k -= tree[pos]; }
    }
    return pos + 1;
  };
  let best = Infinity, size = 0;
  for (let j = x; j < nums.length; j++) {
    add(rank.get(nums[j - x])!);
    size++;
    const c = prefix(rank.get(nums[j])!);
    if (c > 0) best = Math.min(best, nums[j] - vals[kth(c) - 1]);
    if (c < size) best = Math.min(best, vals[kth(c + 1) - 1] - nums[j]);
    if (best === 0) return 0;
  }
  return best;
}

