class Solution:
    def closestFarPair(self, nums: List[int], x: int) -> int:
        if x == 0:
            return 0
        vals = sorted(set(nums))
        m = len(vals)
        rank = {v: i + 1 for i, v in enumerate(vals)}
        tree = [0] * (m + 1)
        top = 1
        while top * 2 <= m:
            top *= 2

        def add(i):
            while i <= m:
                tree[i] += 1
                i += i & -i

        def prefix(i):
            s = 0
            while i > 0:
                s += tree[i]
                i -= i & -i
            return s

        def kth(k):  # rank of the k-th smallest inserted value
            pos, step = 0, top
            while step:
                if pos + step <= m and tree[pos + step] < k:
                    pos += step
                    k -= tree[pos]
                step >>= 1
            return pos + 1

        best = float("inf")
        for j in range(x, len(nums)):
            add(rank[nums[j - x]])
            size = j - x + 1
            c = prefix(rank[nums[j]])
            if c > 0:
                best = min(best, nums[j] - vals[kth(c) - 1])
            if c < size:
                best = min(best, vals[kth(c + 1) - 1] - nums[j])
            if best == 0:
                return 0
        return best

